from collections import Counter
def f(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    others=[c for c in cnt if c!=bg]
    def seglen(c):
        tot=0
        for i in range(h):
            j=0
            while j<w:
                if g[i][j]==c:
                    k=j
                    while k<w and g[i][k]==c: k+=1
                    tot+=max(k-j,1); j=k
                else: j+=1
        for j in range(w):
            i=0
            while i<h:
                if g[i][j]==c:
                    k=i
                    while k<h and g[k][j]==c: k+=1
                    tot+=max(k-i,1); i=k
                else: i+=1
        return tot
    anc=max(others,key=seglen); mk=[c for c in others if c!=anc][0]
    acr=[(i,j) for i in range(h) for j in range(w) if g[i][j]==anc]
    vert = len({j for _,j in acr})==1   # vertical segment -> horizontal rays
    out=[[g[i][j] for j in range(w)] for i in range(h)]
    # gather anchor cells by row/col groups
    rowsmap={}
    for i,j in acr: rowsmap.setdefault(i,[]).append(j)
    colsmap={}
    for i,j in acr: colsmap.setdefault(j,[]).append(i)
    # horizontal-ray groups (vertical segs): rows with multiple anchor cols
    hr=[r for r,js in rowsmap.items() if len(js)>1]
    vr=[c for c,rs in colsmap.items() if len(rs)>1]
    for r in hr:
        js=sorted(rowsmap[r]); lo,hi=js[0],js[-1]
        # direction: toward other anchors (left if other anchors mostly left, etc.) choose inward
        others_r=[rr for rr in hr if rr!=r]
        dirL = min(others_r) if others_r else None
        if dirL is None:
            dirL = min(colsmap) if min(colsmap)<lo else max(colsmap)
        step = -1 if dirL<lo else 1
        for j in range(lo+step, hi+step, step):
            out[r][j]=mk
    for c in vr:
        rs=sorted(colsmap[c]); lo,hi=rs[0],rs[-1]
        others_c=[cc for cc in vr if cc!=c]
        if not others_c:
            dirU = min(rowsmap) if min(rowsmap)<lo else max(rowsmap)
        else:
            dirU = min(others_c) if min(others_c)<lo else max(others_c)
        step = -1 if dirU<lo else 1
        for i in range(lo+step, hi+step, step):
            out[i][c]=mk
    # markers -> 4 anywhere? In demos markers inside rays became 4; markers elsewhere (d3: none elsewhere). Assume all markers -> 4.
    for i in range(h):
        for j in range(w):
            if g[i][j]==mk: out[i][j]=4
    return out
