from collections import Counter
def f3(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    items=[c for c in cnt if c!=bg]
    def dist(i,j): return max(abs(i-h//2),abs(j-w//2))
    emit=max(items,key=lambda c:max(dist(i,j) for i in range(h) for j in range(w) if g[i][j]==c))
    tgt=[c for c in items if c!=emit][0]
    segs=[]
    for i in range(h):
        j=0
        while j<w:
            if g[i][j]==emit:
                k=j
                while k<w and g[i][k]==emit: k+=1
                segs.append(('h',i,0,k-1)); j=k
            else: j+=1
    for j in range(w):
        i=0
        while i<h:
            if g[i][j]==emit:
                k=i
                while k<h and g[k][j]==emit: k+=1
                segs.append(('v',j,i,k-1)); i=k
            else: i+=1
    out=[[g[i][j] for j in range(w)] for i in range(h)]
    T=[(r,c) for r in range(h) for c in range(w) if g[r][c]==tgt]
    for typ,linepos,s,e in segs:
        along=[p for p in T if (typ=='v' and p[0]==linepos) or (typ=='h' and p[1]==linepos)]
        hit=None
        if along:
            hit=min(along,key=lambda p:(min((p[1]-e)**2,(p[1]-s)**2)+(p[0]-linepos)**2))
            tp=hit[linepos if typ=='h' else 1]
            step = 1 if tp>e else -1
        else:
            continue
        # paint from segment edge toward target along the line direction
        for rp in (s,e):
            rr=rp+step
            while True:
                if not(0<=rr<h if typ=='v' else 0<=rr<w): break
                v=g[rr][linepos] if typ=='v' else g[linepos][rr]
                if v==tgt: 
                    out[rr][linepos]=4 if typ=='v' else out[linepos][rr]=4; break
                if v!=bg: break
                out[rr][linepos]=emit if typ=='v' else out[linepos][rr]=emit
                rr+=step
    for i in range(h):
        for j in range(w):
            if g[i][j]==tgt: out[i][j]=4
    return out
