def runs(g, c):
    h=len(g); w=len(g[0])
    res=[]
    for i in range(h):
        j=0
        while j<w:
            if g[i][j]==c:
                k=j
                while k<w and g[i][k]==c: k+=1
                res.append(('h',i,j,k-1)); j=k
            else: j+=1
    for j in range(w):
        i=0
        while i<h:
            if g[i][j]==c:
                k=i
                while k<h and g[k][j]==c: k+=1
                res.append(('v',j,i,k-1)); i=k
            else: i+=1
    return res

def endpoints(seg):
    typ,pos,a,b=seg
    if typ=='h': return [(pos,a),(pos,b)]
    else: return [(a,pos),(b,pos)]

def f(g, mode='both'):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    items=[c for c in cnt if c!=bg]
    # emit color: minority color (fewer cells)
    emit=min(items,key=lambda c:sum(1 for r in g for v in r if v==c))
    tgt=[c for c in items if c!=emit][0]
    segs=runs(g,emit)
    out=[[g[i][j] for j in range(w)] for i in range(h)]
    T=set((r,c) for r in range(h) for c in range(w) if g[r][c]==tgt)
    for seg in segs:
        for rp in endpoints(seg):
            for step in (-1,1):
                # direction: perpendicular to seg orientation, sign=step
                if seg[0]=='v':
                    cc=rp[1]+step
                    rr=rp[0]
                    while True:
                        if not(0<=rr<h): break
                        v=g[rr][cc]
                        if v==emit: break
                        if v!=bg:
                            if v==tgt: out[rr][cc]=4
                            break
                        out[rr][cc]=emit
                        rr+=1
                        if rr==rp[0]: break
                else:
                    rr=rp[0]+step
                    cc=rp[1]
                    while True:
                        if not(0<=cc<w): break
                        v=g[rr][cc]
                        if v==emit: break
                        if v!=bg:
                            if v==tgt: out[rr][cc]=4
                            break
                        out[rr][cc]=emit
                        cc+=1
    for i in range(h):
        for j in range(w):
            if g[i][j]==tgt: out[i][j]=4
    return out

