def segs_runs(g,c,minlen=2):
    h=len(g); w=len(g[0]); res=[]
    for i in range(h):
        j=0
        while j<w:
            if g[i][j]==c: k=j
            elif True: j+=1; continue
            k=j
            while k<w and g[i][k]==c: k+=1
            if k-j>=minlen: res.append(('h',i,j,k-1))
            j=k
    for j in range(w):
        i=0
        while i<h:
            if g[i][j]==c: k=i
            else: i+=1; continue
            k=i
            while k<h and g[k][j]==c: k+=1
            if k-i>=minlen: res.append(('v',j,i,k-1))
            i=k
    return res

def f(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    cnt=Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    others=[c for c in cnt if c!=bg]
    # anchors = color with a run length>=2, else minority
    anchor=None
    for c in others:
        if any(len(s)>=2 for s in segs_runs(g,c)): anchor=c; break
    tgt=[c for c in others if c!=anchor][0]
    A=set(segs_runs(g,anchor))
    T={(r,c) for r in range(h) for c in range(w) if g[r][c]==tgt}
    out=[r[:] for r in g]
    # markers become 4 always
    for r in range(h):
        for c in range(w):
            if out[r][c]==tgt: out[r][c]=4
    for seg in A:
        typ,pos,a,b=seg
        perps=[(-1,0),(1,0)] if typ=='v' else [(0,-1),(0,1)]
        # direction: into interior
        inside=(-1 if pos==0 else 1) if typ=='v' else (-1 if pos==w-1 else 1)
        for sign in [inside]:
            for rp in ((a,),()) if False else ([b] if typ=='h' else [b]):
                pass
        cells=[(a,pos),(b,pos)] if typ=='v' else [(pos,a),(pos,b)]
        for rp in cells:
            R,C=rp+(sign,(1 if typ=='v' else 0) if len(rp)==2 else (0 if typ=='h' else 0))
            while 0<=R<h and 0<=C<w:
                v=g[R][C]
                if v==tgt: out[R][C]=4; break
                if v!=bg: break
                out[R][C]=emit if False else tgt; 
                R+=(1 if typ=='v' else 0); C+=(1 if typ=='h' else 0)
    return out
