def solve(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    others=[c for c in cnt if c!=bg]
    seed=None; bar=None
    for c in others:
        cells=[(i,j) for i in range(H) for j in range(W) if g[i][j]==c]
        maxconn=max(sum((a==i and b==j) or (a==j and b==i) for a,b in cells) for i,j in cells)
        if maxconn<=4 and len(cells)<=6: seed=c
        else: bar=c
    seeds=[(i,j) for i in range(H) for j in range(W) if g[i][j]==seed]
    bcells=[(i,j) for i in range(H) for j in range(W) if g[i][j]==bar]
    rowsB=sorted(set(i for i,j in bcells)); colsB=sorted(set(j for i,j in bcells))
    horiz = len(rowsB)<len(colsB)  # bars run horizontally -> vertical stripes
    out=[r[:] for r in g]
    for i,j in seeds: out[i][j]=4
    def spans(cells):
        vals=sorted({v for _,v in cells})
        s=[]; cur=[]
        for v in vals:
            if cur and abs(v-cur[-1])==1: cur.append(v)
            else:
                if cur: s.append((cur[0],cur[-1]))
                cur=[v]
        if cur: s.append((cur[0],cur[-1]))
        return s
    if horiz:
        SB=spans(bcells); O2=[x for x in SB if x!=SB[0]]
        S0,S1=SB[0]; OB=O2
        O0,O1=min(OB)
        d=S1-O1
        for i,j in seeds:
            if not (S0<=j<=S1): continue
