from collections import Counter
def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    used=[[False]*W for _ in range(H)]; pieces=[]
    for r in range(H):
        c=0
        while c<W:
            if g[r][c]!=bg and not used[r][c]:
                c0=c
                while c<W and g[r][c]==g[r][c0]: c+=1
                if c-c0>=2: pieces.append(('h',r,c0,c-1,g[r][c0],list(range(c0,c))))
                for i in range(c0,c): used[r][i]=True
            c+=1
    for c in range(W):
        r=0
        while r<H:
            if g[r][c]!=bg and not used[r][c]:
                r0=r
                while r<H and g[r][c]==g[r0][c]: r+=1
                if r-r0>=2: pieces.append(('v',c,r0,r-1,g[r0][c],list(range(r0,r))))
                for i in range(r0,r): used[i][c]=True
            r+=1
    singles=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg and not used[r][c]]
    out=[row[:] for row in g]
    for p in pieces:
        if p[0]=='h':
            pc,pstart,pend,col=1,p[1],p[2],p[3]
            span=set(range(pstart,pend+1))
            # beams on column = single's column if in span else nearest span column (demo5: farthest?) -> nearest for now
            beams=[]
            for (sr,sc,scol) in singles:
                if sc in span:
                    beams.append((sc,sr,'single_col'))
                else:
                    beams.append((min(span,key=lambda cc:abs(cc-sc)),sr,'fallback'))
            for bc,(sr,_,_) in beams:
                if sr in [s[0] for s in singles]:
                    # toward single: from piece row pc, direction toward single row
                    d=1 if sr>pc else -1
                    rr=pc+d
                    while 0<=rr<H:
                        if g[rr][bc]==bg: out[rr][bc]=scol
                        elif g[rr][bc]==scol: out[rr][bc]=4; break
                        else: break
                        rr+=d
                else:
                    # unmapped: full column toward edge away from... demo1: from bottom piece up to edge
                    d=-1  # default: toward the other piece / edge
                    rr=pc+d
                    while 0<=rr<H:
                        if g[rr][bc]==bg: out[rr][bc]=scol
                        elif g[rr][bc]==scol: out[rr][bc]=4; break
                        else: break
                        rr+=d
        else:  # v piece: beams horizontal on row
            pc=pstart; pstart,pend=1,p[2],p[3]
            span=set(range(pstart,pend+1))
            for (sr,sc,scol) in singles:
                if sr in span:
                    beams_rows=[sr]
                else:
                    beams_rows=[min(span,key=lambda rr:abs(rr-sr))]
                for br in beams_rows:
                    d=1 if sc>pc else -1
                    c_=pc+d
                    while 0<=c_<W:
                        if g[br][c_]==bg: out[br][c_]=scol
                        elif g[br][c_]==scol: out[br][c_]=4; break
                        else: break
                        c_+=d
    return out

